/**
 * Default dispatch decisions for the PagerDuty channel: turn auth derived
 * from the event's agent, the title and message a turn starts with, which
 * lifecycle events dispatch when no `onIncident` hook exists, and the
 * stream handlers that post replies back to the incident.
 */
import { PAGERDUTY_TOKEN_ENV, pagerDutyChannelClient } from "./api.js";
import { resolvePagerDutySecret } from "./secrets.js";
import { PAGERDUTY_USER_ID_ENV, resolvePagerDutySelfUserIds } from "./self-user.js";
/**
 * Derive the turn's auth from who made the change: a PagerDuty user, a
 * service integration, or PagerDuty itself. The webhook subscriber is not
 * the turn principal (same pattern as `defaultGitHubAuth`).
 */
export function defaultPagerDutyAuth(ctx) {
    const agent = ctx.agent;
    const isUser = agent?.type === "user_reference" || agent?.type === "user";
    const attributes = {
        conversation_kind: "incident",
        event_type: ctx.eventType,
        event_id: ctx.eventId,
        issuer: ctx.accountSubdomain === undefined ? "pagerduty" : `pagerduty:${ctx.accountSubdomain}`,
    };
    if (ctx.incidentId !== undefined) {
        attributes.incident_id = ctx.incidentId;
    }
    if (ctx.incidentKey !== undefined) {
        attributes.incident_key = ctx.incidentKey;
    }
    if (ctx.deliveryId !== undefined) {
        attributes.delivery_id = ctx.deliveryId;
    }
    if (agent !== undefined) {
        attributes.subject = agent.id;
    }
    return {
        authenticator: "pagerduty-webhook",
        principalId: agent === undefined ? "pagerduty" : `pagerduty:${agent.id}`,
        principalType: isUser ? "user" : "service",
        attributes,
    };
}
export function defaultPagerDutyTitle(ctx, incident) {
    if (incident?.number !== undefined && incident.title !== undefined) {
        return `PagerDuty #${incident.number}: ${incident.title}`;
    }
    return ctx.incidentId === undefined
        ? `PagerDuty ${ctx.eventType}`
        : `PagerDuty incident ${ctx.incidentId}`;
}
/** The facts of a lifecycle event, one per line, for the turn's first message. */
export function defaultPagerDutyIncidentMessage(ctx, event) {
    const incident = event.incident;
    return [
        `PagerDuty ${ctx.eventType}: ${incident.number === undefined ? incident.id : `#${incident.number}`}`,
        ...(incident.title === undefined ? [] : [`Title: ${incident.title}`]),
        ...(incident.status === undefined ? [] : [`Status: ${incident.status}`]),
        ...(incident.urgency === undefined ? [] : [`Urgency: ${incident.urgency}`]),
        ...(incident.service?.summary === undefined ? [] : [`Service: ${incident.service.summary}`]),
        ...(incident.priority?.summary === undefined ? [] : [`Priority: ${incident.priority.summary}`]),
        ...(incident.incidentKey === undefined ? [] : [`Incident key: ${incident.incidentKey}`]),
        ...(incident.htmlUrl === undefined ? [] : [`URL: ${incident.htmlUrl}`]),
        ...(ctx.agent?.summary === undefined ? [] : [`By: ${ctx.agent.summary}`]),
        ...(ctx.occurredAt === undefined ? [] : [`Occurred at: ${ctx.occurredAt}`]),
        "Handle this PagerDuty incident event.",
    ].join("\n");
}
/**
 * Default gate when no `onIncident` hook is declared: a new or reopened
 * incident starts a turn as the event's agent. Acknowledgements,
 * escalations, and resolves are acknowledged without one.
 */
export function defaultPagerDutyIncidentDispatch(ctx, event) {
    if (event.eventType !== "incident.triggered" && event.eventType !== "incident.reopened") {
        return null;
    }
    return { auth: defaultPagerDutyAuth(ctx) };
}
const PAGERDUTY_FAILURE_NOTE = "The agent hit an error while handling this incident. Check the agent's session for details.";
/**
 * Opt-in delivery (`deliverReplies: true`): post each completed assistant
 * reply as a note on the session's incident, and a short note when a turn
 * or session fails. Skipped when the session names no incident or is an
 * eval run, or when the channel has no token (a read-only agent).
 *
 * A posted note comes back as an `incident.annotated` event, which only the
 * echo skip keeps from starting another turn. So nothing is posted until the
 * agent's own PagerDuty user resolves (see `selfUserIds`); until then each
 * skipped note logs a warning.
 */
export function buildDefaultPagerDutyEvents(options) {
    if (options.deliverReplies !== true) {
        return {};
    }
    const postNote = async (state, content) => {
        if (state.incidentId === null ||
            resolvePagerDutySecret(options.token, PAGERDUTY_TOKEN_ENV) === undefined) {
            return;
        }
        if ((await resolvePagerDutySelfUserIds({ options })).size === 0) {
            console.warn(`[bdk/pagerduty] warn not posting a reply note to incident ${state.incidentId}: the agent's own PagerDuty user is unknown, so the note would come back as a new event. Set ${PAGERDUTY_USER_ID_ENV} or selfUserIds, or use a token that names one user.`);
            return;
        }
        try {
            await pagerDutyChannelClient(options).addNote({ incidentId: state.incidentId, content });
        }
        catch (error) {
            console.warn(`[bdk/pagerduty] warn could not post a note to incident ${state.incidentId}: ${error instanceof Error ? error.message : String(error)}`);
        }
    };
    return {
        async "message.completed"(event, channel, ctx) {
            if (ctx.session.purpose === "eval" ||
                event.data.parentCallId !== undefined ||
                event.data.finishReason === "tool_call" ||
                event.data.text === "") {
                return;
            }
            await postNote(channel.state, event.data.text);
        },
        async "turn.failed"(_event, channel, ctx) {
            if (ctx.session.purpose !== "eval") {
                await postNote(channel.state, PAGERDUTY_FAILURE_NOTE);
            }
        },
        async "session.failed"(_event, channel, ctx) {
            if (ctx.session.purpose !== "eval") {
                await postNote(channel.state, PAGERDUTY_FAILURE_NOTE);
            }
        },
    };
}
